/**
 * Comprehensive Test Bed of ASCII & Unicode Diagrams and their Target Mermaid Counterparts.
 *
 * Covers standard diagram archetypes generated by Gemini, Claude, and ChatGPT:
 * 1. Split & Merge Architecture (CQRS / Dual-Path)
 * 2. 1-to-N Fan-Out Tree (Domain Aggregate Decomposition)
 * 3. Comparison / Architectural Tension (with "vs." edge label)
 * 4. Horizontal Sequential Pipeline (LR flow)
 * 5. Decision Tree with Branching (Diamond / Yes-No paths)
 * 6. Event-Driven Architecture (Pub/Sub & Multiple Consumers)
 * 7. Cyclic State Machine (Feedback / Retry Loop)
 * 8. Multi-Tier Layered Architecture (Stacked layers)
 * 9. Negative Controls (Tables, Code Blocks - must NOT convert)
 */

export interface DiagramTestCase {
  id: string;
  name: string;
  category: 'architecture' | 'fan_out' | 'comparison' | 'pipeline' | 'decision' | 'event_driven' | 'state_machine' | 'layered' | 'negative_control';
  direction: 'TD' | 'LR' | 'none';
  description: string;
  ascii: string;
  expectedMermaid: string | null;
  nodeCount: number;
  edgeCount: number;
  features: string[];
}

